B=[['拉丁 peccare → 晚期拉丁 impeccabilis','犯错、犯罪 → 不会犯罪的'],['法语 impeccable／晚期拉丁形式 → 英语 impeccable','不会犯罪 → 没有可挑剔之处']]
W=[
E('impeccable','/ɪmˈpekəbəl/','无可挑剔的；完美无瑕的','拿放大镜想挑出一个毛病，却几乎找不到。','im- 是否定 in- 在 p 前的变体，pecc- 来自 peccare 犯错、犯罪，-able 对应可、能。经法语或直接来自晚期拉丁 impeccabilis。',B,'impeccable manners 是礼仪挑不出毛病，impeccable timing 是时机拿捏得恰到好处。这个词早期说不会犯罪，现代通常是很强的赞美，不要求对象涉及宗教或道德。衣着、服务、表达和履历都能用。','impeccable manners；impeccable taste；impeccable timing；an impeccable record。','good 只是好，impeccable 强调几乎无可挑剔。不要把它拆成 peck 啄；也不要误以为只能形容人的品德。',('Her impeccable timing turned a simple joke into the highlight of the evening.','她把时机拿捏得恰到好处，让一个简单笑话成了当晚的亮点。'),('The hotel is known for its impeccable service.','这家酒店以无可挑剔的服务著称。'),sources=['https://www.etymonline.com/word/impeccable','https://www.oxfordlearnersdictionaries.com/definition/english/impeccable']),
E('impeccably','/ɪmˈpekəbli/','无可挑剔地；十分得体地；完美地','某件事从头到尾做得很妥帖，连细节都几乎挑不出错。','英语 impeccable + -ly，词尾 -able 在副词中变成 -ably。',B+[['英语 impeccable → impeccably','无可挑剔的 → 以无可挑剔的方式']],'impeccably dressed 是穿得非常整洁得体，不是必须昂贵或华丽。impeccably organized 是安排得周全，细节也处理好了。它修饰的是穿着、举止、安排等表现方式。','impeccably dressed；impeccably behaved；impeccably organized。','impeccable 修饰名词或作表语；impeccably 修饰动作或分词。说 impeccable service，但说 impeccably dressed。',('He arrived impeccably dressed in a simple dark suit.','他穿着一身简洁的深色西装到场，打扮得十分得体。'),('The event was impeccably organized from registration to the final session.','从签到到最后一场活动，整个安排都井然有序、无可挑剔。'),sources=['https://en.wiktionary.org/wiki/impeccably#English','https://www.oxfordlearnersdictionaries.com/definition/english/impeccably']),
E('peccadillo','英 /ˌpekəˈdɪləʊ/；美 /ˌpekəˈdɪloʊ/','小过失；小毛病','不是把事说成完全没错，而是把它放进小过错那一格。','借自西班牙语 pecadillo，是 pecado 罪、过错的小称形式；pecado 来自拉丁 peccatum，关联 peccare 犯错。',[['拉丁 peccare → peccatum → 西班牙 pecado','犯错 → 过错、罪'],['西班牙 pecadillo → 英语 peccadillo','小过错；被看作不严重的毛病']],'peccadillo 是说话人觉得不太严重、可以容忍的小过失。常见复数 peccadilloes 或 peccadillos。它也可能被用来淡化问题，所以读新闻时要分清：这是事实的客观程度，还是某个人故意轻描淡写。','forgive somebody’s peccadilloes；minor peccadilloes；dismiss something as a peccadillo。','mistake 是广泛的错误；peccadillo 多指行为或道德上的小过错，语气带宽容或轻描淡写。不是拼写错误的常规叫法。',('His friends forgave his occasional peccadilloes.','朋友们原谅了他偶尔的小过失。'),('She refused to dismiss the repeated dishonesty as a mere peccadillo.','她不肯把一再的不诚实轻描淡写地当成一个小毛病。'),sources=['https://www.etymonline.com/word/peccadillo','https://www.oxfordlearnersdictionaries.com/definition/english/peccadillo'])]
ROOT=dict(id='C0976',meaning='犯错；过失；犯罪',core='PECC = ERR / SIN',image='一边是把过错缩小，成为 peccadillo 小过失；另一边是否定能犯错，成为 impeccable 无可挑剔。',intro='拉丁 peccare 表示犯错、做错事、犯罪。这个词族不必死记成宗教术语：现代 impeccable 常赞扬服务、礼仪和时机，peccadillo 则把行为上的错误说得较轻。',forms='impeccable 的 im- 是否定，后接 p 时 n 同化为 m；peccadillo 的 -illo 来自西班牙语小称。peccare 更远的词源有争议，不把它必然说成脚走错一步。',branches=[['无可挑剔','impeccable, impeccably'],['小过失','peccadillo']],contrasts='impeccable 是赞美没有可挑剔之处；peccadillo 承认有过错，只是把它说得较小。后者有时是在替行为开脱，要看上下文。',practice='Impeccable manners leave little to criticize; a peccadillo is a fault treated as minor.\n\n无可挑剔的礼仪让人很难找出毛病；peccadillo 则是被视为不严重的过失。',words=[x['word'] for x in W],exclude={'peccant':'低频正式词，先略过','peccavi':'低频拉丁借词，先略过'})
if __name__=='__main__':
 for name,data in [('roots_pecc',[ROOT]),('words_pecc',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
